import React, { useState } from 'react';
import { Activity, Leaf } from 'lucide-react';
import AgriAdvisoryInterface from './agri_advisory_interface';
import StressTestDashboard from './stress_test_dashboard';

type Tab = 'advisory' | 'stress-test';

const App = () => {
  const [activeTab, setActiveTab] = useState<Tab>('advisory');

  return (
    <div className="relative min-h-screen">
      {/* Floating Tab Switcher */}
      <div className="fixed top-3 left-1/2 -translate-x-1/2 z-[100] flex items-center bg-white/90 backdrop-blur-md border border-slate-200/80 rounded-full shadow-lg px-1.5 py-1.5 gap-1">
        <button
          onClick={() => setActiveTab('advisory')}
          className={`flex items-center gap-2 px-5 py-2 rounded-full text-sm font-medium transition-all ${
            activeTab === 'advisory'
              ? 'bg-emerald-600 text-white shadow-sm'
              : 'text-slate-600 hover:bg-slate-100'
          }`}
        >
          <Leaf size={15} />
          Advisory
        </button>
        <button
          onClick={() => setActiveTab('stress-test')}
          className={`flex items-center gap-2 px-5 py-2 rounded-full text-sm font-medium transition-all ${
            activeTab === 'stress-test'
              ? 'bg-emerald-600 text-white shadow-sm'
              : 'text-slate-600 hover:bg-slate-100'
          }`}
        >
          <Activity size={15} />
          Stress Test
        </button>
      </div>

      {/* Tab Content */}
      <div className={activeTab === 'advisory' ? '' : 'hidden'}>
        <AgriAdvisoryInterface />
      </div>
      <div className={activeTab === 'stress-test' ? '' : 'hidden'}>
        <StressTestDashboard />
      </div>
    </div>
  );
};

export default App;
