// ─── Types ──────────────────────────────────────────────────────────────────
interface RequestResult {
  id: number;
  status: 'pending' | 'running' | 'success' | 'error';
  startTime: number;
  endTime?: number;
  ttfb?: number;
  totalTime?: number;
  tokensReceived?: number;
  error?: string;
  responseSize?: number;
  concurrencyLevel?: number;
}

interface TestConfig {
  totalRequests: number;
  concurrency: number;
  streaming: boolean;
  temperature: number;
  maxTokens: number;
  promptPreset: string;
  customPrompt: string;
}

interface TestSummary {
  totalRequests: number;
  successCount: number;
  errorCount: number;
  avgLatency: number;
  p50Latency: number;
  p95Latency: number;
  p99Latency: number;
  minLatency: number;
  maxLatency: number;
  throughput: number;
  avgTtfb: number;
  totalDuration: number;
  tokensPerSecond: number;
}

interface SweepResult {
  concurrency: number;
  avgLatency: number;
  p50Latency: number;
  p95Latency: number;
  p99Latency: number;
  throughput: number;
  errorRate: number;
  avgTtfb: number;
  successCount: number;
  errorCount: number;
}

