const ProgressBar = ({ current, total, startTime }: { current: number; total: number; startTime: number }) => {
  const pct = total > 0 ? (current / total) * 100 : 0;
  const elapsed = Date.now() - startTime;
  const eta = current > 0 ? ((elapsed / current) * (total - current)) : 0;

  return (
    <div className="bg-white/80 border border-slate-200/80 rounded-xl p-4 mb-6">
      <div className="flex items-center justify-between mb-2">
        <span className="text-sm font-medium text-slate-700">
          Progress: {current} / {total} requests
        </span>
        <div className="flex items-center gap-4 text-xs text-slate-500">
          <span>Elapsed: {formatMs(elapsed)}</span>
          {current > 0 && current < total && <span>ETA: {formatMs(eta)}</span>}
        </div>
      </div>
      <div className="w-full bg-slate-100 rounded-full h-3 overflow-hidden">
        <div
          className="h-full rounded-full bg-gradient-to-r from-emerald-500 to-teal-500 transition-all duration-300 ease-out"
          style={{ width: `${pct}%` }}
        />
      </div>
      <div className="text-right text-xs text-slate-400 mt-1">{pct.toFixed(1)}%</div>
    </div>
  );
};

