// ═══════════════════════════════════════════════════════════════════════════
//  MAIN COMPONENT
// ═══════════════════════════════════════════════════════════════════════════
const StressTestDashboard = () => {
  // ─── Config State ───────────────────────────────────────────────────────
  const [config, setConfig] = useState<TestConfig>({
    totalRequests: 10,
    concurrency: 2,
    streaming: true,
    temperature: 0.8,
    maxTokens: 5000,
    promptPreset: 'default',
    customPrompt: '',
  });

  const [testMode, setTestMode] = useState<'single' | 'sweep'>('single');
  const [sweepConfig, setSweepConfig] = useState({
    requestsPerLevel: 5,
    levels: '1,2,4,8',
  });

  // ─── Config Sections ───────────────────────────────────────────────────
  const [sections, setSections] = useState({
    testMode: true,
    parameters: true,
    prompt: false,
    advanced: false,
  });

  // ─── Test State ─────────────────────────────────────────────────────────
  const [isRunning, setIsRunning] = useState(false);
  const [results, setResults] = useState<RequestResult[]>([]);
  const [summary, setSummary] = useState<TestSummary | null>(null);
  const [sweepResults, setSweepResults] = useState<SweepResult[]>([]);
  const [testStartTime, setTestStartTime] = useState(0);
  const [completedCount, setCompletedCount] = useState(0);
  const [totalTestRequests, setTotalTestRequests] = useState(0);
  const [liveLog, setLiveLog] = useState<string[]>([]);

  const abortRef = useRef(false);
  const resultsRef = useRef<RequestResult[]>([]);

  // ─── Reset ──────────────────────────────────────────────────────────────
  const resetResults = useCallback(() => {
    setResults([]);
    setSummary(null);
    setSweepResults([]);
    setCompletedCount(0);
    setTotalTestRequests(0);
    setLiveLog([]);
    resultsRef.current = [];
  }, []);

  const addLog = useCallback((msg: string) => {
    setLiveLog(prev => [...prev.slice(-99), `[${new Date().toLocaleTimeString()}] ${msg}`]);
  }, []);

  // ─── Get Prompt ─────────────────────────────────────────────────────────
  const getPrompt = useCallback((): string => {
    if (config.promptPreset === 'custom') return config.customPrompt;
    return PROMPT_PRESETS[config.promptPreset]?.prompt || PROMPT_PRESETS.default.prompt;
  }, [config.promptPreset, config.customPrompt]);

  // ─── Single Request Execution ─────────────────────────────────────────
  const executeRequest = useCallback(async (
    id: number,
    prompt: string,
    streaming: boolean,
    onUpdate: (r: RequestResult) => void,
  ): Promise<RequestResult> => {
    const result: RequestResult = {
      id,
      status: 'running',
      startTime: performance.now(),
    };
    onUpdate(result);

    try {
      const body: any = {
        model: API_CONFIG.saarthiModel,
        messages: [{ role: 'user', content: prompt }],
        stream: streaming,
        temperature: config.temperature,
        max_tokens: config.maxTokens,
      };

      const fetchStart = performance.now();

      const response = await fetch(API_CONFIG.saarthiBaseUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        const errText = await response.text();
        throw new Error(`HTTP ${response.status}: ${errText.slice(0, 200)}`);
      }

      if (streaming && response.body) {
        // Streaming mode — measure TTFB and count tokens
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let firstChunk = true;
        let tokenCount = 0;
        let totalBytes = 0;

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          if (firstChunk) {
            result.ttfb = performance.now() - fetchStart;
            firstChunk = false;
          }

          const text = decoder.decode(value, { stream: true });
          totalBytes += value.byteLength;

          // Parse SSE chunks and count tokens
          const lines = text.split('\n');
          for (const line of lines) {
            if (line.startsWith('data: ') && line !== 'data: [DONE]') {
              try {
                const json = JSON.parse(line.slice(6));
                const content = json.choices?.[0]?.delta?.content;
                if (content) tokenCount++;
              } catch { /* skip parse errors */ }
            }
          }
        }

        result.tokensReceived = tokenCount;
        result.responseSize = totalBytes;
      } else {
        // Non-streaming mode
        result.ttfb = performance.now() - fetchStart;
        const data = await response.json();
        const content = data.choices?.[0]?.message?.content || '';
        result.tokensReceived = content.split(/\s+/).length; // approximate
        result.responseSize = JSON.stringify(data).length;
      }

      result.endTime = performance.now();
      result.totalTime = result.endTime - result.startTime;
      result.status = 'success';
    } catch (err: any) {
      result.endTime = performance.now();
      result.totalTime = result.endTime - result.startTime;
      result.status = 'error';
      result.error = err.message || 'Unknown error';
    }

    onUpdate(result);
    return result;
  }, [config.temperature, config.maxTokens]);

  // ─── Concurrency Runner ───────────────────────────────────────────────
  const runWithConcurrency = useCallback(async (
    totalReqs: number,
    concurrency: number,
    prompt: string,
    streaming: boolean,
    onResult: (r: RequestResult) => void,
    idOffset = 0,
    concurrencyLabel?: number,
  ): Promise<RequestResult[]> => {
    const allResults: RequestResult[] = [];
    let nextId = idOffset;
    const running: Promise<void>[] = [];

    const runOne = async () => {
      if (abortRef.current) return;
      const myId = nextId++;
      if (myId - idOffset >= totalReqs) return;

      const result = await executeRequest(myId, prompt, streaming, (r) => {
        r.concurrencyLevel = concurrencyLabel ?? concurrency;
        onResult(r);
      });
      allResults.push(result);

      // Start next if available
      if (!abortRef.current && nextId - idOffset < totalReqs) {
        await runOne();
      }
    };

    // Launch initial concurrent workers
    const workers = Math.min(concurrency, totalReqs);
    for (let i = 0; i < workers; i++) {
      running.push(runOne());
    }

    await Promise.all(running);
    return allResults;
  }, [executeRequest]);

  // ─── Compute Summary ─────────────────────────────────────────────────
  const computeSummary = useCallback((results: RequestResult[], totalDuration: number): TestSummary => {
    const successful = results.filter(r => r.status === 'success');
    const latencies = successful.map(r => r.totalTime!).filter(Boolean);
    const ttfbs = successful.map(r => r.ttfb!).filter(Boolean);
    const tokens = successful.reduce((sum, r) => sum + (r.tokensReceived || 0), 0);

    return {
      totalRequests: results.length,
      successCount: successful.length,
      errorCount: results.filter(r => r.status === 'error').length,
      avgLatency: latencies.length > 0 ? latencies.reduce((a, b) => a + b, 0) / latencies.length : 0,
      p50Latency: percentile(latencies, 50),
      p95Latency: percentile(latencies, 95),
      p99Latency: percentile(latencies, 99),
      minLatency: latencies.length > 0 ? Math.min(...latencies) : 0,
      maxLatency: latencies.length > 0 ? Math.max(...latencies) : 0,
      throughput: totalDuration > 0 ? (successful.length / (totalDuration / 1000)) : 0,
      avgTtfb: ttfbs.length > 0 ? ttfbs.reduce((a, b) => a + b, 0) / ttfbs.length : 0,
      totalDuration,
      tokensPerSecond: totalDuration > 0 ? (tokens / (totalDuration / 1000)) : 0,
    };
  }, []);

  // ─── Run Single Test ──────────────────────────────────────────────────
  const runSingleTest = useCallback(async () => {
    resetResults();
    abortRef.current = false;
    setIsRunning(true);
    setTotalTestRequests(config.totalRequests);
    const start = performance.now();
    setTestStartTime(Date.now());

    addLog(`Starting stress test: ${config.totalRequests} requests, concurrency ${config.concurrency}, streaming=${config.streaming}`);

    const prompt = getPrompt();
    let completed = 0;

    const allResults = await runWithConcurrency(
      config.totalRequests,
      config.concurrency,
      prompt,
      config.streaming,
      (r) => {
        if (r.status === 'success' || r.status === 'error') {
          completed++;
          setCompletedCount(completed);
          resultsRef.current = [...resultsRef.current, r];
          setResults([...resultsRef.current]);
          addLog(`Request #${r.id} ${r.status}: ${formatMs(r.totalTime || 0)}${r.ttfb ? ` (TTFB: ${formatMs(r.ttfb)})` : ''}`);
        }
      },
    );

    const totalDuration = performance.now() - start;
    const finalSummary = computeSummary(allResults, totalDuration);
    setSummary(finalSummary);
    setIsRunning(false);
    addLog(`Test complete in ${formatMs(totalDuration)}. Success: ${finalSummary.successCount}/${finalSummary.totalRequests}, Throughput: ${finalSummary.throughput.toFixed(2)} req/s`);
  }, [config, resetResults, addLog, getPrompt, runWithConcurrency, computeSummary]);

  // ─── Run Sweep Test ───────────────────────────────────────────────────
  const runSweepTest = useCallback(async () => {
    resetResults();
    abortRef.current = false;
    setIsRunning(true);
    const start = performance.now();
    setTestStartTime(Date.now());

    const levels = sweepConfig.levels.split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n) && n > 0);
    const totalReqs = levels.length * sweepConfig.requestsPerLevel;
    setTotalTestRequests(totalReqs);

    addLog(`Starting concurrency sweep: levels=[${levels.join(',')}], ${sweepConfig.requestsPerLevel} requests per level`);

    const prompt = getPrompt();
    const allSweepResults: SweepResult[] = [];
    let globalCompleted = 0;
    let idOffset = 0;

    for (const level of levels) {
      if (abortRef.current) break;

      addLog(`--- Concurrency level: ${level} ---`);
      const levelStart = performance.now();

      const levelResults = await runWithConcurrency(
        sweepConfig.requestsPerLevel,
        level,
        prompt,
        config.streaming,
        (r) => {
          if (r.status === 'success' || r.status === 'error') {
            globalCompleted++;
            setCompletedCount(globalCompleted);
            resultsRef.current = [...resultsRef.current, r];
            setResults([...resultsRef.current]);
          }
        },
        idOffset,
        level,
      );

      idOffset += sweepConfig.requestsPerLevel;
      const levelDuration = performance.now() - levelStart;
      const levelSummary = computeSummary(levelResults, levelDuration);

      const sweepResult: SweepResult = {
        concurrency: level,
        avgLatency: levelSummary.avgLatency,
        p50Latency: levelSummary.p50Latency,
        p95Latency: levelSummary.p95Latency,
        p99Latency: levelSummary.p99Latency,
        throughput: levelSummary.throughput,
        errorRate: levelSummary.totalRequests > 0
          ? (levelSummary.errorCount / levelSummary.totalRequests) * 100
          : 0,
        avgTtfb: levelSummary.avgTtfb,
        successCount: levelSummary.successCount,
        errorCount: levelSummary.errorCount,
      };

      allSweepResults.push(sweepResult);
      setSweepResults([...allSweepResults]);

      addLog(`Level ${level}: Avg=${formatMs(sweepResult.avgLatency)}, P95=${formatMs(sweepResult.p95Latency)}, Throughput=${sweepResult.throughput.toFixed(2)} req/s, Errors=${sweepResult.errorRate.toFixed(1)}%`);
    }

    const totalDuration = performance.now() - start;
    const finalSummary = computeSummary(resultsRef.current, totalDuration);
    setSummary(finalSummary);
    setIsRunning(false);
    addLog(`Sweep complete in ${formatMs(totalDuration)}`);
  }, [sweepConfig, config.streaming, resetResults, addLog, getPrompt, runWithConcurrency, computeSummary]);

  // ─── Stop Test ────────────────────────────────────────────────────────
  const stopTest = useCallback(() => {
    abortRef.current = true;
    addLog('Test aborted by user');
  }, [addLog]);

  // ─── Export Results ───────────────────────────────────────────────────
  const exportResults = useCallback(() => {
    const data = {
      config,
      testMode,
      sweepConfig: testMode === 'sweep' ? sweepConfig : undefined,
      summary,
      sweepResults: testMode === 'sweep' ? sweepResults : undefined,
      results: results.map(r => ({
        id: r.id,
        status: r.status,
        totalTime: r.totalTime,
        ttfb: r.ttfb,
        tokensReceived: r.tokensReceived,
        responseSize: r.responseSize,
        error: r.error,
        concurrencyLevel: r.concurrencyLevel,
      })),
      timestamp: new Date().toISOString(),
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `stress-test-${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }, [config, testMode, sweepConfig, summary, sweepResults, results]);

  // ─── Derived Data ─────────────────────────────────────────────────────
  const completedResults = results.filter(r => r.status === 'success' || r.status === 'error');

  // Latency distribution histogram
  const latencyDistribution = (() => {
    const latencies = completedResults.filter(r => r.status === 'success').map(r => r.totalTime!);
    if (latencies.length === 0) return [];

    const min = Math.min(...latencies);
    const max = Math.max(...latencies);
    const bucketCount = Math.min(12, Math.max(5, Math.ceil(latencies.length / 3)));
    const bucketSize = (max - min) / bucketCount || 1;

    const buckets: { range: string; count: number; from: number; to: number }[] = [];
    for (let i = 0; i < bucketCount; i++) {
      const from = min + i * bucketSize;
      const to = from + bucketSize;
      buckets.push({
        range: `${formatMs(from)}`,
        count: latencies.filter(l => l >= from && (i === bucketCount - 1 ? l <= to : l < to)).length,
        from,
        to,
      });
    }
    return buckets;
  })();

  // Latency over time (request order)
  const latencyTimeline = completedResults
    .filter(r => r.status === 'success')
    .sort((a, b) => a.id - b.id)
    .map(r => ({
      request: `#${r.id}`,
      latency: Math.round(r.totalTime || 0),
      ttfb: Math.round(r.ttfb || 0),
    }));

  // Success/Error pie
  const pieData = (() => {
    const s = completedResults.filter(r => r.status === 'success').length;
    const e = completedResults.filter(r => r.status === 'error').length;
    if (s === 0 && e === 0) return [];
    return [
      { name: 'Success', value: s },
      { name: 'Error', value: e },
    ];
  })();

  // TTFB vs Total Time scatter
  const scatterData = completedResults
    .filter(r => r.status === 'success' && r.ttfb)
    .map(r => ({
      ttfb: Math.round(r.ttfb!),
      total: Math.round(r.totalTime!),
      id: r.id,
    }));

  // ─── Render ─────────────────────────────────────────────────────────────
  return (
    <div className="min-h-screen bg-[#eef2f6]">
      <div className="relative flex h-screen">
        {/* ────── Sidebar Config Panel ────── */}
        <div className="w-80 bg-[#f6f8fa] border-r border-slate-200/80 flex flex-col">
          {/* Header */}
          <div className="px-6 py-5 border-b border-slate-200">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center shadow-sm">
                <Activity size={20} className="text-white" />
              </div>
              <div>
                <h1 className="text-base font-bold text-slate-900 tracking-tight">Stress Test</h1>
                <p className="text-xs text-slate-500">Model Performance Benchmarking</p>
              </div>
            </div>
          </div>

          {/* Config Sections */}
          <div className="flex-1 overflow-y-auto p-3 space-y-2 scrollbar-thin">
            {/* Test Mode */}
            <ConfigSection
              title="Test Mode"
              icon={Layers}
              isOpen={sections.testMode}
              onToggle={() => setSections(p => ({ ...p, testMode: !p.testMode }))}
            >
              <div className="pt-2 space-y-3">
                <div className="flex gap-2">
                  <button
                    onClick={() => setTestMode('single')}
                    className={`flex-1 px-3 py-2 rounded-lg text-xs font-medium transition-all ${
                      testMode === 'single'
                        ? 'bg-emerald-100 text-emerald-800 border border-emerald-300'
                        : 'bg-white/60 text-slate-600 border border-slate-200 hover:bg-slate-50'
                    }`}
                  >
                    Single Run
                  </button>
                  <button
                    onClick={() => setTestMode('sweep')}
                    className={`flex-1 px-3 py-2 rounded-lg text-xs font-medium transition-all ${
                      testMode === 'sweep'
                        ? 'bg-emerald-100 text-emerald-800 border border-emerald-300'
                        : 'bg-white/60 text-slate-600 border border-slate-200 hover:bg-slate-50'
                    }`}
                  >
                    Concurrency Sweep
                  </button>
                </div>

                {testMode === 'single' ? (
                  <>
                    <div>
                      <label className="text-xs font-medium text-slate-600 mb-1 block">Total Requests</label>
                      <input
                        type="number"
                        min={1}
                        max={200}
                        value={config.totalRequests}
                        onChange={e => setConfig(p => ({ ...p, totalRequests: parseInt(e.target.value) || 1 }))}
                        className="w-full px-3 py-2 bg-white/80 border border-slate-200/80 rounded-lg text-sm text-slate-700 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400"
                      />
                    </div>
                    <div>
                      <label className="text-xs font-medium text-slate-600 mb-1 block">Concurrency</label>
                      <input
                        type="number"
                        min={1}
                        max={50}
                        value={config.concurrency}
                        onChange={e => setConfig(p => ({ ...p, concurrency: parseInt(e.target.value) || 1 }))}
                        className="w-full px-3 py-2 bg-white/80 border border-slate-200/80 rounded-lg text-sm text-slate-700 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400"
                      />
                      <p className="text-[10px] text-slate-400 mt-1">Max simultaneous requests</p>
                    </div>
                  </>
                ) : (
                  <>
                    <div>
                      <label className="text-xs font-medium text-slate-600 mb-1 block">Requests per Level</label>
                      <input
                        type="number"
                        min={1}
                        max={50}
                        value={sweepConfig.requestsPerLevel}
                        onChange={e => setSweepConfig(p => ({ ...p, requestsPerLevel: parseInt(e.target.value) || 1 }))}
                        className="w-full px-3 py-2 bg-white/80 border border-slate-200/80 rounded-lg text-sm text-slate-700 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400"
                      />
                    </div>
                    <div>
                      <label className="text-xs font-medium text-slate-600 mb-1 block">Concurrency Levels</label>
                      <input
                        type="text"
                        value={sweepConfig.levels}
                        onChange={e => setSweepConfig(p => ({ ...p, levels: e.target.value }))}
                        className="w-full px-3 py-2 bg-white/80 border border-slate-200/80 rounded-lg text-sm text-slate-700 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400"
                        placeholder="1,2,4,8,16"
                      />
                      <p className="text-[10px] text-slate-400 mt-1">Comma-separated concurrency levels to test</p>
                    </div>
                  </>
                )}
              </div>
            </ConfigSection>

            {/* Parameters */}
            <ConfigSection
              title="Model Parameters"
              icon={Settings}
              isOpen={sections.parameters}
              onToggle={() => setSections(p => ({ ...p, parameters: !p.parameters }))}
            >
              <div className="pt-2 space-y-3">
                <div className="flex items-center justify-between">
                  <label className="text-xs font-medium text-slate-600">Streaming</label>
                  <button
                    onClick={() => setConfig(p => ({ ...p, streaming: !p.streaming }))}
                    className={`relative w-10 h-5 rounded-full transition-colors ${
                      config.streaming ? 'bg-emerald-500' : 'bg-slate-300'
                    }`}
                  >
                    <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${
                      config.streaming ? 'translate-x-5' : 'translate-x-0.5'
                    }`} />
                  </button>
                </div>
                <div>
                  <label className="text-xs font-medium text-slate-600 mb-1 block">Temperature: {config.temperature}</label>
                  <input
                    type="range"
                    min={0}
                    max={2}
                    step={0.1}
                    value={config.temperature}
                    onChange={e => setConfig(p => ({ ...p, temperature: parseFloat(e.target.value) }))}
                    className="w-full accent-emerald-500"
                  />
                </div>
                <div>
                  <label className="text-xs font-medium text-slate-600 mb-1 block">Max Tokens</label>
                  <input
                    type="number"
                    min={10}
                    max={10000}
                    value={config.maxTokens}
                    onChange={e => setConfig(p => ({ ...p, maxTokens: parseInt(e.target.value) || 100 }))}
                    className="w-full px-3 py-2 bg-white/80 border border-slate-200/80 rounded-lg text-sm text-slate-700 focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400"
                  />
                </div>
                <div className="text-[10px] text-slate-400 p-2 bg-slate-50 rounded-lg border border-slate-100">
                  <strong>Model:</strong> {API_CONFIG.saarthiModel}<br />
                  <strong>Endpoint:</strong> {API_CONFIG.saarthiBaseUrl}
                </div>
              </div>
            </ConfigSection>

            {/* Prompt Selection */}
            <ConfigSection
              title="Test Prompt"
              icon={Hash}
              isOpen={sections.prompt}
              onToggle={() => setSections(p => ({ ...p, prompt: !p.prompt }))}
            >
              <div className="pt-2 space-y-3">
                <select
                  value={config.promptPreset}
                  onChange={e => setConfig(p => ({ ...p, promptPreset: e.target.value }))}
                  className="w-full px-3 py-2 bg-white/80 border border-slate-200/80 rounded-lg text-sm text-slate-700"
                >
                  {Object.entries(PROMPT_PRESETS).map(([key, { label }]) => (
                    <option key={key} value={key}>{label}</option>
                  ))}
                  <option value="custom">Custom Prompt</option>
                </select>

                {config.promptPreset === 'custom' && (
                  <textarea
                    value={config.customPrompt}
                    onChange={e => setConfig(p => ({ ...p, customPrompt: e.target.value }))}
                    rows={6}
                    placeholder="Enter your custom prompt..."
                    className="w-full px-3 py-2 bg-white/80 border border-slate-200/80 rounded-lg text-xs text-slate-700 font-mono resize-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400"
                  />
                )}

                {config.promptPreset !== 'custom' && (
                  <div className="text-[10px] text-slate-400 p-2 bg-slate-50 rounded-lg border border-slate-100 max-h-24 overflow-y-auto font-mono whitespace-pre-wrap">
                    {PROMPT_PRESETS[config.promptPreset]?.prompt.slice(-200)}...
                  </div>
                )}
              </div>
            </ConfigSection>
          </div>

          {/* Action Button */}
          <div className="p-4 border-t border-slate-200/80 space-y-2">
            {isRunning ? (
              <button
                onClick={stopTest}
                className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-red-500 hover:bg-red-600 text-white rounded-xl font-medium text-sm transition-all shadow-sm"
              >
                <Square size={16} />
                Stop Test
              </button>
            ) : (
              <button
                onClick={testMode === 'single' ? runSingleTest : runSweepTest}
                className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 text-white rounded-xl font-medium text-sm transition-all shadow-sm"
              >
                <Play size={16} />
                {testMode === 'single' ? 'Run Stress Test' : 'Run Concurrency Sweep'}
              </button>
            )}

            {completedResults.length > 0 && (
              <div className="flex gap-2">
                <button
                  onClick={resetResults}
                  className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2 bg-white/60 border border-slate-200 text-slate-600 rounded-lg text-xs font-medium hover:bg-slate-50 transition-all"
                >
                  <RotateCcw size={12} />
                  Clear
                </button>
                <button
                  onClick={exportResults}
                  className="flex-1 flex items-center justify-center gap-1.5 px-3 py-2 bg-white/60 border border-slate-200 text-slate-600 rounded-lg text-xs font-medium hover:bg-slate-50 transition-all"
                >
                  <Download size={12} />
                  Export
                </button>
              </div>
            )}
          </div>
        </div>

        {/* ────── Main Results Area ────── */}
        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Top Bar */}
          <div className="h-14 border-b border-slate-200/80 bg-white/60 flex items-center justify-between px-6">
            <div className="flex items-center gap-3">
              <BarChart3 size={18} className="text-emerald-600" />
              <h2 className="text-sm font-semibold text-slate-800">
                {testMode === 'single' ? 'Stress Test Results' : 'Concurrency Sweep Results'}
              </h2>
              {isRunning && (
                <span className="flex items-center gap-1.5 px-2.5 py-1 bg-amber-50 text-amber-700 border border-amber-200 rounded-full text-xs font-medium">
                  <span className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse" />
                  Running
                </span>
              )}
            </div>
            <div className="text-xs text-slate-400">
              {API_CONFIG.saarthiModel}
            </div>
          </div>

          {/* Scrollable Results */}
          <div className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-thin">
            {/* Empty State */}
            {completedResults.length === 0 && !isRunning && (
              <div className="flex flex-col items-center justify-center h-full text-center">
                <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-emerald-100 to-teal-100 flex items-center justify-center mb-4">
                  <Activity size={32} className="text-emerald-500" />
                </div>
                <h3 className="text-lg font-semibold text-slate-700 mb-2">No Test Results Yet</h3>
                <p className="text-sm text-slate-500 max-w-md">
                  Configure your test parameters in the sidebar and click "Run Stress Test" to begin benchmarking.
                  Results will appear here in real-time.
                </p>
                <div className="mt-6 grid grid-cols-3 gap-4 text-center">
                  <div className="p-4 bg-white/60 rounded-xl border border-slate-200/60">
                    <Cpu size={20} className="text-emerald-500 mx-auto mb-2" />
                    <div className="text-xs font-medium text-slate-700">Concurrent Requests</div>
                    <div className="text-[10px] text-slate-400 mt-1">Test max concurrent load</div>
                  </div>
                  <div className="p-4 bg-white/60 rounded-xl border border-slate-200/60">
                    <Timer size={20} className="text-blue-500 mx-auto mb-2" />
                    <div className="text-xs font-medium text-slate-700">Latency Metrics</div>
                    <div className="text-[10px] text-slate-400 mt-1">P50, P95, P99 latencies</div>
                  </div>
                  <div className="p-4 bg-white/60 rounded-xl border border-slate-200/60">
                    <TrendingUp size={20} className="text-purple-500 mx-auto mb-2" />
                    <div className="text-xs font-medium text-slate-700">Throughput</div>
                    <div className="text-[10px] text-slate-400 mt-1">Requests/sec analysis</div>
                  </div>
                </div>
              </div>
            )}

            {/* Progress Bar (during test) */}
            {isRunning && totalTestRequests > 0 && (
              <ProgressBar current={completedCount} total={totalTestRequests} startTime={testStartTime} />
            )}

            {/* Summary Cards */}
            {summary && (
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-3">
                <MetricCard
                  label="Total"
                  value={summary.totalRequests.toString()}
                  subValue={`${summary.successCount} OK / ${summary.errorCount} Err`}
                  icon={Hash}
                  color="emerald"
                />
                <MetricCard
                  label="Avg Latency"
                  value={formatMs(summary.avgLatency)}
                  subValue={`Min: ${formatMs(summary.minLatency)}`}
                  icon={Clock}
                  color="blue"
                />
                <MetricCard
                  label="P50"
                  value={formatMs(summary.p50Latency)}
                  icon={Timer}
                  color="teal"
                />
                <MetricCard
                  label="P95"
                  value={formatMs(summary.p95Latency)}
                  icon={Timer}
                  color="amber"
                />
                <MetricCard
                  label="P99"
                  value={formatMs(summary.p99Latency)}
                  icon={Timer}
                  color="red"
                />
                <MetricCard
                  label="Throughput"
                  value={`${summary.throughput.toFixed(2)}`}
                  subValue="requests/sec"
                  icon={TrendingUp}
                  color="purple"
                />
                <MetricCard
                  label="Avg TTFB"
                  value={formatMs(summary.avgTtfb)}
                  subValue={summary.tokensPerSecond > 0 ? `${summary.tokensPerSecond.toFixed(1)} tok/s` : undefined}
                  icon={Zap}
                  color="indigo"
                />
              </div>
            )}

            {/* Charts Grid */}
            {completedResults.length > 0 && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Latency Distribution */}
                {latencyDistribution.length > 0 && (
                  <div className="bg-white/80 border border-slate-200/80 rounded-xl p-5">
                    <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                      <BarChart3 size={14} className="text-emerald-600" />
                      Latency Distribution
                    </h3>
                    <ResponsiveContainer width="100%" height={250}>
                      <BarChart data={latencyDistribution}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                        <XAxis dataKey="range" tick={{ fontSize: 10 }} angle={-30} textAnchor="end" height={50} />
                        <YAxis tick={{ fontSize: 10 }} label={{ value: 'Count', angle: -90, position: 'insideLeft', style: { fontSize: 10 } }} />
                        <Tooltip content={<CustomTooltip />} />
                        <Bar dataKey="count" fill={CHART_COLORS.primary} radius={[4, 4, 0, 0]} name="Requests" />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                )}

                {/* Latency Over Time */}
                {latencyTimeline.length > 0 && (
                  <div className="bg-white/80 border border-slate-200/80 rounded-xl p-5">
                    <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                      <TrendingUp size={14} className="text-blue-600" />
                      Latency Over Time
                    </h3>
                    <ResponsiveContainer width="100%" height={250}>
                      <LineChart data={latencyTimeline}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                        <XAxis dataKey="request" tick={{ fontSize: 10 }} />
                        <YAxis tick={{ fontSize: 10 }} label={{ value: 'ms', angle: -90, position: 'insideLeft', style: { fontSize: 10 } }} />
                        <Tooltip content={<CustomTooltip />} />
                        <Legend wrapperStyle={{ fontSize: 11 }} />
                        <Line type="monotone" dataKey="latency" stroke={CHART_COLORS.primary} strokeWidth={2} dot={{ r: 3 }} name="Total Latency" />
                        {latencyTimeline.some(d => d.ttfb > 0) && (
                          <Line type="monotone" dataKey="ttfb" stroke={CHART_COLORS.accent} strokeWidth={2} dot={{ r: 3 }} name="TTFB" strokeDasharray="5 5" />
                        )}
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                )}

                {/* TTFB vs Total Time Scatter */}
                {scatterData.length > 2 && (
                  <div className="bg-white/80 border border-slate-200/80 rounded-xl p-5">
                    <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                      <Zap size={14} className="text-indigo-600" />
                      TTFB vs Total Latency
                    </h3>
                    <ResponsiveContainer width="100%" height={250}>
                      <ScatterChart>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                        <XAxis dataKey="ttfb" name="TTFB (ms)" tick={{ fontSize: 10 }} label={{ value: 'TTFB (ms)', position: 'insideBottom', offset: -5, style: { fontSize: 10 } }} />
                        <YAxis dataKey="total" name="Total (ms)" tick={{ fontSize: 10 }} label={{ value: 'Total (ms)', angle: -90, position: 'insideLeft', style: { fontSize: 10 } }} />
                        <Tooltip cursor={{ strokeDasharray: '3 3' }} />
                        <Scatter data={scatterData} fill={CHART_COLORS.purple}>
                          {scatterData.map((_, index) => (
                            <Cell key={index} fill={CHART_COLORS.purple} opacity={0.7} />
                          ))}
                        </Scatter>
                      </ScatterChart>
                    </ResponsiveContainer>
                  </div>
                )}

                {/* Success / Error Pie */}
                {pieData.length > 0 && (
                  <div className="bg-white/80 border border-slate-200/80 rounded-xl p-5">
                    <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                      <CheckCircle size={14} className="text-emerald-600" />
                      Success / Error Rate
                    </h3>
                    <ResponsiveContainer width="100%" height={250}>
                      <PieChart>
                        <Pie
                          data={pieData}
                          cx="50%"
                          cy="50%"
                          innerRadius={60}
                          outerRadius={90}
                          paddingAngle={4}
                          dataKey="value"
                          label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                        >
                          {pieData.map((_, index) => (
                            <Cell key={index} fill={PIE_COLORS[index]} />
                          ))}
                        </Pie>
                        <Tooltip />
                        <Legend wrapperStyle={{ fontSize: 11 }} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                )}

                {/* Sweep: Concurrency vs Latency */}
                {testMode === 'sweep' && sweepResults.length > 0 && (
                  <div className="bg-white/80 border border-slate-200/80 rounded-xl p-5 lg:col-span-2">
                    <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                      <Layers size={14} className="text-purple-600" />
                      Concurrency vs Latency
                    </h3>
                    <ResponsiveContainer width="100%" height={300}>
                      <LineChart data={sweepResults}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                        <XAxis dataKey="concurrency" tick={{ fontSize: 10 }} label={{ value: 'Concurrency', position: 'insideBottom', offset: -5, style: { fontSize: 10 } }} />
                        <YAxis tick={{ fontSize: 10 }} label={{ value: 'Latency (ms)', angle: -90, position: 'insideLeft', style: { fontSize: 10 } }} />
                        <Tooltip content={<CustomTooltip />} />
                        <Legend wrapperStyle={{ fontSize: 11 }} />
                        <Line type="monotone" dataKey="avgLatency" stroke={CHART_COLORS.primary} strokeWidth={2} dot={{ r: 4 }} name="Avg Latency" />
                        <Line type="monotone" dataKey="p50Latency" stroke={CHART_COLORS.blue} strokeWidth={2} dot={{ r: 4 }} name="P50" />
                        <Line type="monotone" dataKey="p95Latency" stroke={CHART_COLORS.warning} strokeWidth={2} dot={{ r: 4 }} name="P95" />
                        <Line type="monotone" dataKey="p99Latency" stroke={CHART_COLORS.error} strokeWidth={2} dot={{ r: 4 }} name="P99" />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                )}

                {/* Sweep: Concurrency vs Throughput */}
                {testMode === 'sweep' && sweepResults.length > 0 && (
                  <div className="bg-white/80 border border-slate-200/80 rounded-xl p-5 lg:col-span-2">
                    <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                      <TrendingUp size={14} className="text-teal-600" />
                      Concurrency vs Throughput
                    </h3>
                    <ResponsiveContainer width="100%" height={300}>
                      <AreaChart data={sweepResults}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                        <XAxis dataKey="concurrency" tick={{ fontSize: 10 }} label={{ value: 'Concurrency', position: 'insideBottom', offset: -5, style: { fontSize: 10 } }} />
                        <YAxis tick={{ fontSize: 10 }} label={{ value: 'req/s', angle: -90, position: 'insideLeft', style: { fontSize: 10 } }} />
                        <Tooltip content={<CustomTooltip />} />
                        <Legend wrapperStyle={{ fontSize: 11 }} />
                        <Area type="monotone" dataKey="throughput" stroke={CHART_COLORS.secondary} fill={CHART_COLORS.secondary} fillOpacity={0.15} strokeWidth={2} dot={{ r: 4 }} name="Throughput (req/s)" />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                )}

                {/* Sweep: Error Rate */}
                {testMode === 'sweep' && sweepResults.length > 0 && sweepResults.some(s => s.errorRate > 0) && (
                  <div className="bg-white/80 border border-slate-200/80 rounded-xl p-5 lg:col-span-2">
                    <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                      <AlertTriangle size={14} className="text-red-600" />
                      Concurrency vs Error Rate
                    </h3>
                    <ResponsiveContainer width="100%" height={250}>
                      <BarChart data={sweepResults}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                        <XAxis dataKey="concurrency" tick={{ fontSize: 10 }} />
                        <YAxis tick={{ fontSize: 10 }} label={{ value: '%', angle: -90, position: 'insideLeft', style: { fontSize: 10 } }} />
                        <Tooltip content={<CustomTooltip />} />
                        <Bar dataKey="errorRate" fill={CHART_COLORS.error} radius={[4, 4, 0, 0]} name="Error Rate (%)" />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                )}
              </div>
            )}

            {/* Request Details Table */}
            {completedResults.length > 0 && (
              <div className="bg-white/80 border border-slate-200/80 rounded-xl overflow-hidden">
                <div className="px-5 py-3 border-b border-slate-200/60 flex items-center justify-between">
                  <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                    <Activity size={14} className="text-emerald-600" />
                    Request Details
                  </h3>
                  <span className="text-xs text-slate-400">{completedResults.length} requests</span>
                </div>
                <div className="overflow-x-auto max-h-80 overflow-y-auto scrollbar-thin">
                  <table className="w-full text-xs">
                    <thead className="bg-slate-50/80 sticky top-0">
                      <tr>
                        <th className="text-left px-4 py-2.5 text-slate-500 font-medium">#</th>
                        <th className="text-left px-4 py-2.5 text-slate-500 font-medium">Status</th>
                        <th className="text-right px-4 py-2.5 text-slate-500 font-medium">TTFB</th>
                        <th className="text-right px-4 py-2.5 text-slate-500 font-medium">Total Time</th>
                        <th className="text-right px-4 py-2.5 text-slate-500 font-medium">Tokens</th>
                        <th className="text-right px-4 py-2.5 text-slate-500 font-medium">Size</th>
                        {testMode === 'sweep' && (
                          <th className="text-right px-4 py-2.5 text-slate-500 font-medium">Concurrency</th>
                        )}
                        <th className="text-left px-4 py-2.5 text-slate-500 font-medium">Error</th>
                      </tr>
                    </thead>
                    <tbody>
                      {completedResults.sort((a, b) => a.id - b.id).map(r => (
                        <tr key={r.id} className="border-t border-slate-100 hover:bg-slate-50/50 transition-colors">
                          <td className="px-4 py-2 text-slate-600 font-mono">{r.id}</td>
                          <td className="px-4 py-2">
                            {r.status === 'success' ? (
                              <span className="inline-flex items-center gap-1 text-emerald-600">
                                <CheckCircle size={12} /> OK
                              </span>
                            ) : (
                              <span className="inline-flex items-center gap-1 text-red-500">
                                <XCircle size={12} /> Error
                              </span>
                            )}
                          </td>
                          <td className="px-4 py-2 text-right text-slate-600 font-mono">
                            {r.ttfb ? formatMs(r.ttfb) : '—'}
                          </td>
                          <td className="px-4 py-2 text-right text-slate-600 font-mono">
                            {r.totalTime ? formatMs(r.totalTime) : '—'}
                          </td>
                          <td className="px-4 py-2 text-right text-slate-600 font-mono">
                            {r.tokensReceived ?? '—'}
                          </td>
                          <td className="px-4 py-2 text-right text-slate-600 font-mono">
                            {r.responseSize ? `${(r.responseSize / 1024).toFixed(1)}KB` : '—'}
                          </td>
                          {testMode === 'sweep' && (
                            <td className="px-4 py-2 text-right text-slate-600 font-mono">
                              {r.concurrencyLevel ?? '—'}
                            </td>
                          )}
                          <td className="px-4 py-2 text-slate-400 max-w-xs truncate">
                            {r.error || '—'}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Live Log */}
            {liveLog.length > 0 && (
              <div className="bg-slate-900 border border-slate-700 rounded-xl overflow-hidden">
                <div className="px-4 py-2.5 border-b border-slate-700 flex items-center justify-between">
                  <span className="text-xs font-medium text-slate-300 flex items-center gap-2">
                    <Activity size={12} className="text-emerald-400" />
                    Live Log
                  </span>
                  <span className="text-[10px] text-slate-500">{liveLog.length} entries</span>
                </div>
                <div className="p-4 max-h-48 overflow-y-auto scrollbar-thin font-mono text-[11px] text-slate-300 space-y-0.5">
                  {liveLog.map((msg, i) => (
                    <div key={i} className={msg.includes('Error') || msg.includes('error') ? 'text-red-400' : msg.includes('complete') ? 'text-emerald-400' : ''}>
                      {msg}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="h-12 border-t border-slate-200/80 flex items-center justify-center bg-[#f6f8fa]">
            <p className="text-xs text-slate-400">
              Powered by Soket AI Labs : Part of IndiaAI initiative
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StressTestDashboard;
